<?php

namespace Database\Seeders;

use Database\Seeders\Concerns\LoadsTestProductionData;
use Database\Seeders\Support\TestProductionLinks;
use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Schema;

/**
 * The execution side of the test production dataset: production orders, operations, progress logs, reservations,
 * requisitions, issues, receipts, schedules, WIP, event timelines — and the stock those completed orders imply.
 * Same conventions as TestProductionMasterDataSeeder.
 */
class TestProductionExecutionSeeder extends Seeder
{
    use LoadsTestProductionData;

    /** Stock every test product starts with in its warehouse; the quantities the test orders issue are added on top. */
    public const BASE_OPENING_QTY = 100;

    /** Warehouse (by code) the opening stock of a product type is booked into. */
    private const HOME_WAREHOUSE = [
        'raw_material' => 'WH-RM-TBL',
        'semi_finished' => 'WH-WIP-TBL',
        'finished_good' => 'WH-FG-TBL',
    ];

    public function run(?int $tenantId = null): void
    {
        $tenantId = $this->resolveTenantId($tenantId);
        $links = new TestProductionLinks($tenantId);

        Schema::disableForeignKeyConstraints();

        try {
            foreach ($this->tables() as $table => $rows) {
                $this->seedTable($table, $rows, $tenantId, $links);
            }

            $this->seedOpeningStock($tenantId, $links);
            $this->postStockMovements($tenantId, $links);
        } finally {
            Schema::enableForeignKeyConstraints();
        }

        $this->command?->info("TestProductionExecutionSeeder completed successfully for Tenant ID {$tenantId}.");
    }

    /**
     * Opening stock for every test product, booked at the time the product was created: BASE_OPENING_QTY in its home
     * warehouse, plus whatever the test orders issue out of each warehouse, so the movements posted below never take a
     * balance under zero.
     */
    private function seedOpeningStock(int $tenantId, TestProductionLinks $links): void
    {
        $warehouses = DB::table('warehouses')->where('tenant_id', $tenantId)->pluck('id', 'code')->all();
        $companyId = $links->companyId();
        $branchId = $links->branchId('HQ');
        $issued = $this->issuedByProductWarehouse($this->productionOrderIssues(), $links);
        $stockColumns = array_flip(Schema::getColumnListing('product_warehouse_stocks'));
        $ledgerColumns = array_flip(Schema::getColumnListing('stock_transactions'));

        foreach (DB::table('products')->where('tenant_id', $tenantId)->where('sku', 'LIKE', 'test-%')->get() as $product) {
            $homeCode = self::HOME_WAREHOUSE[$product->type] ?? 'WH-RM-TBL';
            if (! isset($warehouses[$homeCode])) {
                throw new \RuntimeException("Test production data: warehouse {$homeCode} does not exist (tenant {$tenantId}). AddTestMastersSeeder must run first.");
            }

            $targets = [(int) $warehouses[$homeCode]];
            foreach (array_keys($issued) as $key) {
                [$productId, $warehouseId] = array_map('intval', explode(':', $key));
                if ($productId === (int) $product->id) {
                    $targets[] = $warehouseId;
                }
            }

            $rate = (float) ($product->cost_price ?? 0);
            $total = 0.0;

            foreach (array_unique($targets) as $warehouseId) {
                $qty = self::BASE_OPENING_QTY + ($issued["{$product->id}:{$warehouseId}"] ?? 0.0);
                $total += $qty;
                $at = $product->created_at ?? now();

                DB::table('product_warehouse_stocks')->updateOrInsert(
                    ['tenant_id' => $tenantId, 'product_id' => $product->id, 'warehouse_id' => $warehouseId],
                    array_intersect_key([
                        'company_id' => $companyId, 'branch_id' => $branchId, 'quantity' => $qty, 'available_qty' => $qty, 'reserved_qty' => 0,
                        'unit_cost' => $rate, 'created_at' => $at, 'updated_at' => $at,
                    ], $stockColumns)
                );

                DB::table('stock_transactions')->updateOrInsert(
                    ['tenant_id' => $tenantId, 'product_id' => $product->id, 'warehouse_id' => $warehouseId, 'reference_type' => 'Opening Stock'],
                    array_intersect_key([
                        'company_id' => $companyId, 'branch_id' => $branchId, 'type' => 'IN', 'reference_id' => $product->id, 'quantity' => $qty,
                        'unit_cost' => $rate, 'total_value' => $qty * $rate, 'balance_qty' => $qty, 'created_at' => $at, 'updated_at' => $at,
                    ], $ledgerColumns)
                );
            }

            DB::table('products')->where('id', $product->id)->update(['opening_stock' => $total, 'opening_stock_rate' => $rate]);
        }
    }

    /**
     * The orders are completed: they issued raw material / semi-finished stock and received their output.
     * Post those movements into the stock ledger (OUT "Production Material Issue", IN "Production Order Receipt") and
     * bring the warehouse balances to where they end up, so stock agrees with the orders.
     *
     * Direct ledger rows, not StockService: that service would also post accounting journals, and this data
     * deliberately creates none (the cleaner removes stock journals; stock here has no book value to match).
     * The opening layer of each (product, warehouse) is reduced by what was issued from it — first in, first out.
     */
    private function postStockMovements(int $tenantId, TestProductionLinks $links): void
    {
        $issues = $this->productionOrderIssues();
        $receipts = $this->productionOrderReceipts();
        $companyId = $links->companyId();
        $branchId = $links->branchId('HQ');
        $products = DB::table('products')->where('tenant_id', $tenantId)->whereIn('id', array_merge(
            array_column($issues, 'product_id'),
            array_column($receipts, 'product_id'),
        ))->get()->keyBy('id');

        $events = [];
        foreach ($issues as $issue) {
            $events[] = ['at' => $issue['issued_at'], 'type' => 'OUT', 'reference' => 'Production Material Issue', 'order' => $issue['production_order_id'],
                'product' => (int) $issue['product_id'], 'warehouse' => $links->warehouseId($issue['warehouse']), 'qty' => (float) $issue['quantity_issued']];
        }
        foreach ($receipts as $receipt) {
            $events[] = ['at' => $receipt['received_at'], 'type' => 'IN', 'reference' => 'Production Order Receipt', 'order' => $receipt['production_order_id'],
                'product' => (int) $receipt['product_id'], 'warehouse' => $links->warehouseId($receipt['warehouse']), 'qty' => (float) $receipt['quantity_received']];
        }
        usort($events, fn ($a, $b) => strcmp($a['at'], $b['at']));

        // run again on the same data: take the movements posted last time out first, so nothing is counted twice
        DB::table('stock_transactions')->where('tenant_id', $tenantId)
            ->whereIn('reference_type', ['Production Material Issue', 'Production Order Receipt'])
            ->whereIn('reference_id', array_column($this->productionOrders(), 'id'))->delete();

        $ledgerColumns = array_flip(Schema::getColumnListing('stock_transactions'));
        $stockColumns = array_flip(Schema::getColumnListing('product_warehouse_stocks'));
        $balance = [];    // "product:warehouse" => quantity on hand
        $issuedFrom = []; // "product:warehouse" => quantity issued (taken from the opening layer)

        foreach ($events as $event) {
            $key = $event['product'] . ':' . $event['warehouse'];
            // start from the opening layer, not from the stock row (which already holds the end result after a first run)
            $balance[$key] ??= (float) DB::table('stock_transactions')
                ->where('tenant_id', $tenantId)->where('product_id', $event['product'])->where('warehouse_id', $event['warehouse'])
                ->where('reference_type', 'Opening Stock')->value('quantity');

            $balance[$key] += $event['type'] === 'IN' ? $event['qty'] : -$event['qty'];
            if ($balance[$key] < 0) {
                throw new \RuntimeException("Test production data: stock of product {$event['product']} would drop below zero in warehouse {$event['warehouse']}.");
            }
            if ($event['type'] === 'OUT') {
                $issuedFrom[$key] = ($issuedFrom[$key] ?? 0.0) + $event['qty'];
            }

            $rate = (float) ($products[$event['product']]->unit_cost ?? $products[$event['product']]->cost_price ?? 0);
            DB::table('stock_transactions')->insert(array_intersect_key([
                'tenant_id' => $tenantId, 'company_id' => $companyId, 'branch_id' => $branchId, 'product_id' => $event['product'], 'warehouse_id' => $event['warehouse'],
                'type' => $event['type'], 'reference_type' => $event['reference'], 'reference_id' => $event['order'],
                'quantity' => $event['qty'], 'unit_cost' => $rate, 'total_value' => $event['qty'] * $rate,
                'balance_qty' => $event['type'] === 'IN' ? $event['qty'] : 0,   // same as StockService: an IN row holds its remaining layer, an OUT row 0
                'created_at' => $event['at'], 'updated_at' => $event['at'],
            ], $ledgerColumns));
        }

        foreach ($balance as $key => $quantity) {
            [$productId, $warehouseId] = array_map('intval', explode(':', $key));

            // a received product may have no stock row yet (e.g. a finished good received into WH-MAIN)
            $stock = DB::table('product_warehouse_stocks')->where('tenant_id', $tenantId)->where('product_id', $productId)->where('warehouse_id', $warehouseId);
            $values = ['quantity' => $quantity, 'available_qty' => $quantity, 'updated_at' => now()];

            if ($stock->exists()) {
                $stock->update($values);
            } else {
                $rate = (float) ($products[$productId]->unit_cost ?? $products[$productId]->cost_price ?? 0);
                DB::table('product_warehouse_stocks')->insert(array_intersect_key($values + [
                    'tenant_id' => $tenantId, 'company_id' => $companyId, 'branch_id' => $branchId, 'product_id' => $productId, 'warehouse_id' => $warehouseId,
                    'reserved_qty' => 0, 'unit_cost' => $rate, 'created_at' => now(),
                ], $stockColumns));
            }

            if (isset($issuedFrom[$key])) {
                // the layer left over from the opening stock after the issues
                $opening = DB::table('stock_transactions')->where('tenant_id', $tenantId)->where('product_id', $productId)->where('warehouse_id', $warehouseId)->where('reference_type', 'Opening Stock');
                $layer = (float) $opening->clone()->value('quantity');
                $opening->update(['balance_qty' => max(0, $layer - $issuedFrom[$key])]);
            }
        }
    }

    /**
     * Production orders and what happened on them.
     *
     * @return array<string, array<int, array<string, mixed>>> table => rows, in the order they are loaded
     */
    public function tables(): array
    {
        return [
            'production_orders' => $this->productionOrders(),
            'production_order_operations' => $this->productionOrderOperations(),
            'production_order_operation_dependencies' => $this->productionOrderOperationDependencies(),
            'production_order_progress_logs' => $this->productionOrderProgressLogs(),
            'production_order_reservations' => $this->productionOrderReservations(),
            'production_requisition_slips' => $this->productionRequisitionSlips(),
            'production_requisition_slip_items' => $this->productionRequisitionSlipItems(),
            'production_order_issues' => $this->productionOrderIssues(),
            'production_order_issue_batches' => $this->productionOrderIssueBatches(),
            'production_order_receipts' => $this->productionOrderReceipts(),
            'production_schedules' => $this->productionSchedules(),
            'production_schedule_operations' => $this->productionScheduleOperations(),
            'production_wips' => $this->productionWips(),
            'production_wip_transactions' => $this->productionWipTransactions(),
            'production_event_timelines' => $this->productionEventTimelines(),
            'production_machine_downtimes' => $this->productionMachineDowntimes(),
            'production_machine_state_histories' => $this->productionMachineStateHistories(),
        ];
    }

